/bin/bash -lc "python - <<'PY'
import urllib.request
for u,name in [('https://www.assemblyai.com/docs/api-reference/transcripts/submit','docs'),('https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/assemblyai/types.py','types')]:
 try:
  b=urllib.request.urlopen(u, timeout=20).read(); open('/tmp/assemblyai-'+name,'wb').write(b); print(name,len(b))
 except Exception as e: print(name,type(e).__name__,str(e))
PY"

